1	//! Tier 2's range checks (spec §11 GR-11), called from `props_check.rs`'s
2	//! `check_video`: each wheel's `x`, `y` and `master` −1…1, and its push
3	//! inside the unit circle; and each curve's 2–16 points, x and y 0…1, x
4	//! strictly rising (GR-12), a hue curve's x 0 ≤ x < 360 and its value in
5	//! its domain's range (GR-32); and the qualifier's ranges, each bound in its
6	//! own sentence and low ≤ high (GR-13), then its `blur` 0…1 (GR-35).
7	//!
8	//! The rule is `props_check.rs`'s: a value out of range is NAMED in the
9	//! rule's own sentence, never clamped (an action's end is clamped instead,
10	//! by `actions_clamp_grade.rs`'s `clamp_wheels`). The circle test allows
11	//! [`WHEEL_RIM_TOLERANCE`] past 1, so a rim point made by `cos`/`sin` or
12	//! divided by its `hypot` — the inspector's puck and `clamp_wheels` both
13	//! make one — is never refused; the sentence still says `≤ 1`.
14	
15	use crate::model::{
16	    CurveDomain, Curves, Qualifier, Wheels, CURVE_POINTS_MAX, CURVE_POINTS_MIN, HUE_SOFTNESS_MAX,
17	    HUE_TURN, QUALIFIER_BLUR_MAX, WHEEL_MAX, WHEEL_RIM_TOLERANCE,
18	};
19	use crate::props_check::in_range;
20	
21	/// `Ok` when every wheel is in range and inside the circle; the first
22	/// refusal otherwise, in model order (lift, gamma, gain; x, y, master).
23	pub(crate) fn check_wheels(wheels: &Wheels) -> Result<(), String> {
24	    for (name, wheel) in wheels.named() {
25	        let key = format!("video.wheels.{name}");
26	        in_range(&format!("{key}.x"), wheel.x, -WHEEL_MAX, WHEEL_MAX)?;
27	        in_range(&format!("{key}.y"), wheel.y, -WHEEL_MAX, WHEEL_MAX)?;
28	        in_range(
29	            &format!("{key}.master"),
30	            wheel.master,
31	            -WHEEL_MAX,
32	            WHEEL_MAX,
33	        )?;
34	        if wheel.x * wheel.x + wheel.y * wheel.y > 1.0 + WHEEL_RIM_TOLERANCE {
35	            return Err(format!(
36	                "{key} must lie inside the unit circle (x² + y² ≤ 1), not x {}, y {}",
37	                wheel.x, wheel.y
38	            ));
39	        }
40	    }
41	    Ok(())
42	}
43	
44	/// `Ok` when every curve holds 2–16 points, each x and y 0…1 (bounds
45	/// inclusive) and x strictly rising; the first refusal otherwise, in model
46	/// order (master, red, green, blue, hue_hue, hue_sat), then point order,
47	/// indices 0-based (GR-12). A hue curve's x is 0 ≤ x < 360 and its value
48	/// within its domain's range (GR-32). An identity curve passes: `set_video`
49	/// drops it after this.
50	pub(crate) fn check_curves(curves: &Curves) -> Result<(), String> {
51	    for (name, domain, curve) in curves.named() {
52	        let Some(points) = curve else {
53	            continue;
54	        };
55	        let key = format!("video.curves.{name}");
56	        if !(CURVE_POINTS_MIN..=CURVE_POINTS_MAX).contains(&points.len()) {
57	            return Err(format!(
58	                "{key} needs {CURVE_POINTS_MIN} to {CURVE_POINTS_MAX} points, not {}",
59	                points.len()
60	            ));
61	        }
62	        let (low, high) = domain.value_range();
63	        for (index, point) in points.iter().enumerate() {
64	            if domain == CurveDomain::Tone {
65	                in_range(&format!("{key}[{index}].x"), point[0], 0.0, 1.0)?;
66	            } else if !(point[0].is_finite() && point[0] >= 0.0 && point[0] < HUE_TURN) {
67	                return Err(format!(
68	                    "{key}[{index}].x must be at least 0 and below {HUE_TURN}, not {}",
69	                    point[0]
70	                ));
71	            }
72	            in_range(&format!("{key}[{index}].y"), point[1], low, high)?;
73	            if index > 0 && point[0] <= points[index - 1][0] {
74	                return Err(format!(
75	                    "{key}[{index}].x ({}) must be greater than {key}[{}].x ({})",
76	                    point[0],
77	                    index - 1,
78	                    points[index - 1][0]
79	                ));
80	            }
81	        }
82	    }
83	    Ok(())
84	}
85	
86	/// `Ok` when every present range is inside its bounds (all inclusive, spec
87	/// §11 GR-13): the hue's `center` and `width` 0…360 and its `softness`
88	/// 0…180; each level range's `low`, `high` and `softness` 0…1 and `low ≤
89	/// high`. The first refusal otherwise, in the order hue (centre, width,
90	/// softness), saturation (low, high, softness, then the order), luma the
91	/// same; then `blur` 0…1 (GR-35), last. A bound is compared exactly, so
92	/// 360, 180, 0 and 1 all pass.
93	pub(crate) fn check_qualifier(qualifier: &Qualifier) -> Result<(), String> {
94	    if let Some(hue) = &qualifier.hue {
95	        in_range("video.qualifier.hue.center", hue.center, 0.0, HUE_TURN)?;
96	        in_range("video.qualifier.hue.width", hue.width, 0.0, HUE_TURN)?;
97	        in_range(
98	            "video.qualifier.hue.softness",
99	            hue.softness,
100	            0.0,
101	            HUE_SOFTNESS_MAX,
102	        )?;
103	    }
104	    for (name, range) in qualifier.levels() {
105	        let Some(range) = range else {
106	            continue;
107	        };
108	        let key = format!("video.qualifier.{name}");
109	        in_range(&format!("{key}.low"), range.low, 0.0, 1.0)?;
110	        in_range(&format!("{key}.high"), range.high, 0.0, 1.0)?;
111	        in_range(&format!("{key}.softness"), range.softness, 0.0, 1.0)?;
112	        if range.low > range.high {
113	            return Err(format!(
114	                "{key}.low ({}) must not be greater than {key}.high ({})",
115	                range.low, range.high
116	            ));
117	        }
118	    }
119	    in_range(
120	        "video.qualifier.blur",
121	        qualifier.blur,
122	        0.0,
123	        QUALIFIER_BLUR_MAX,
124	    )
125	}
